Q: Fabric js : how to apply round corner to path &amp; polygon A: <p>I hope you've already found the solution, but if not, I think I managed to solve the problem.</p>
<p>Fabric.js does not have native support for rounded corners on polygons, paths, or triangles. Only <code>Rect</code> supports <code>rx</code> / <code>ry</code>.<br />
Because of that, rounding these shapes must be done by <strong>rebuilding their path manually</strong>.</p>
<p>The main issue both you and I faced was that each time the radius was changed, the shape slowly grew or distorted. This happens when the rounding logic is applied repeatedly on an already-rounded path.</p>
<p>The key insight is:</p>
<p><strong>You must always recompute the rounded path from the original geometry, not from the modified one.</strong></p>
<h3>How the solution works:</h3>
<ol>
<li><p><strong>Preserve the original points</strong></p>
<p>Each polygon or path stores its original vertices in a custom property:</p>
<pre><code>obj.originalPoints = obj.points;

</code></pre>
<p>or, for paths:</p>
<pre><code>obj.originalPoints = getPointsFromPath(obj.path);

</code></pre>
<p>These points are never modified.</p>
</li>
<li><p><strong>Generate a rounded path from raw points</strong></p>
<p>The function <code>getRoundedPolyPath(points, radius)</code>:</p>
<ul>
<li><p>Iterates over triplets of points</p>
</li>
<li><p>Computes edge vectors and their lengths</p>
</li>
<li><p>Clamps the radius so it never exceeds half of the adjacent edges</p>
</li>
<li><p>Replaces sharp corners with quadratic Bézier curves (<code>Q</code> commands)</p>
</li>
</ul>
<p>This produces a valid SVG path string with smooth corners.</p>
</li>
<li><p><strong>Replace the object instead of mutating it</strong></p>
<p>Fabric.js does not allow changing a polygon into a path in place.<br />
So the original object is removed and replaced with a new <code>fabric.Path</code> that:</p>
<ul>
<li><p>Copies transform properties (<code>left</code>, <code>top</code>, <code>scaleX</code>, <code>scaleY</code>, <code>angle</code>, etc.)</p>
</li>
<li><p>Keeps the same visual style</p>
</li>
<li><p>Stores the same <code>originalPoints</code> reference</p>
</li>
</ul>
</li>
<li><p><strong>Keyboard control (w / s)</strong></p>
<p>The &quot;w&quot; and &quot;s&quot; keys only change the <code>radius</code> value.<br />
Every update reuses the same original points, so:</p>
<ul>
<li><p>No cumulative distortion occurs</p>
</li>
<li><p>The shape never grows or shrinks unexpectedly</p>
</li>
<li><p>Increasing and decreasing the radius is fully reversible</p>
</li>
</ul>
</li>
</ol>
<hr />
<h3>Why this avoids the “shape growing” bug:</h3>
<p>If you extract points from the already-rounded path and round them again, each iteration adds new curvature on top of curvature. This compounds numerical error and changes the effective geometry.</p>
<p>By <strong>always recalculating from the untouched original points</strong>, the rounding operation becomes <strong>pure and idempotent</strong>: the same input always produces the same output for a given radius.</p>
<p><div class="snippet" data-lang="js" data-hide="false" data-console="true" data-babel="false" data-babel-preset-react="false" data-babel-preset-ts="false">
<div class="snippet-code">
<pre class="snippet-code-html lang-html prettyprint-override"><code>&lt;!DOCTYPE html&gt;
&lt;html lang="en"&gt;
&lt;head&gt;
  &lt;meta charset="UTF-8" /&gt;
  &lt;title&gt;Fabric.js – Rounded Corners for Shapes&lt;/title&gt;
  &lt;script src="https://cdnjs.cloudflare.com/ajax/libs/fabric.js/5.3.0/fabric.min.js"&gt;&lt;/script&gt;
  &lt;style&gt;
    body { margin: 0; padding: 0; }
    canvas { border: 1px solid #ccc; }
  &lt;/style&gt;
&lt;/head&gt;
&lt;body&gt;
&lt;p&gt;Press the "w" or "s" to decrease or increase the curve radii while with an element selected.&lt;/p&gt;
&lt;canvas id="c" width="700" height="400"&gt;&lt;/canvas&gt;

&lt;script&gt;
  const canvas = new fabric.Canvas('c');
  let currentRadius = 0;

  /* ---------- Helpers ---------- */

  function getRoundedPolyPath(points, radius) {
    if (!points || points.length &lt; 3) return '';

    const path = [];
    for (let i = 0; i &lt; points.length; i++) {
      const p1 = points[i];
      const p2 = points[(i + 1) % points.length];
      const p3 = points[(i + 2) % points.length];

      const dx1 = p2.x - p1.x;
      const dy1 = p2.y - p1.y;
      const dx2 = p3.x - p2.x;
      const dy2 = p3.y - p2.y;

      const len1 = Math.hypot(dx1, dy1);
      const len2 = Math.hypot(dx2, dy2);

      const r = Math.min(radius, len1 / 2, len2 / 2);

      const sx = p2.x - (dx1 / len1) * r;
      const sy = p2.y - (dy1 / len1) * r;
      const ex = p2.x + (dx2 / len2) * r;
      const ey = p2.y + (dy2 / len2) * r;

      if (i === 0) path.push(`M ${sx} ${sy}`);
      else path.push(`L ${sx} ${sy}`);

      path.push(`Q ${p2.x} ${p2.y} ${ex} ${ey}`);
    }

    return path.join(' ') + ' Z';
  }

  function getPointsFromPath(path) {
    const pts = [];
    path.forEach(cmd =&gt; {
      if (cmd[0] === 'M' || cmd[0] === 'L') {
        pts.push({ x: cmd[1], y: cmd[2] });
      }
    });
    return pts;
  }

  function applyRadius(obj, radius) {
    if (obj.type === 'rect') {
      obj.set({ rx: radius, ry: radius });
      return;
    }

    let points;

    if (obj.type === 'polygon') {
      points = obj.originalPoints || obj.points;
    } else if (obj.type === 'path') {
      points = obj.originalPoints || getPointsFromPath(obj.path);
    } else {
      return;
    }

    const pathData = getRoundedPolyPath(points, radius);

    const rounded = new fabric.Path(pathData, {
      fill: obj.fill,
      stroke: obj.stroke,
      strokeWidth: obj.strokeWidth,
      left: obj.left,
      top: obj.top,
      angle: obj.angle,
      scaleX: obj.scaleX,
      scaleY: obj.scaleY,
      originX: obj.originX,
      originY: obj.originY,
      originalPoints: points   // Key point of the solution
    });

    canvas.remove(obj);
    canvas.add(rounded);
    canvas.setActiveObject(rounded);
  }

  /* ---------- Shapes ---------- */

  const rect = new fabric.Rect({
    left: 60,
    top: 60,
    width: 120,
    height: 120,
    fill: '#4CAF50'
  });

  const polygon = new fabric.Polygon([
    { x: 0, y: -60 },
    { x: 60, y: 0 },
    { x: 0, y: 60 },
    { x: -60, y: 0 }
  ], {
    left: 260,
    top: 120,
    fill: '#2196F3'
  });

  polygon.originalPoints = polygon.points;

  const starPoints = [
    { x: 0, y: -60 },
    { x: 14, y: -20 },
    { x: 60, y: -20 },
    { x: 24, y: 10 },
    { x: 38, y: 60 },
    { x: 0, y: 30 },
    { x: -38, y: 60 },
    { x: -24, y: 10 },
    { x: -60, y: -20 },
    { x: -14, y: -20 }
  ];

  const starPath = new fabric.Path(
    getRoundedPolyPath(starPoints, 0),
    {
      left: 480,
      top: 130,
      fill: '#FF9800',
      originalPoints: starPoints
    }
  );

  canvas.add(rect, polygon, starPath);
  canvas.setActiveObject(rect);

  /* ---------- Keyboard Control ---------- */

  document.addEventListener('keydown', e =&gt; {
    const obj = canvas.getActiveObject();
    if (!obj) return;

    if (e.key === 'w') {
      currentRadius += 2;
    } else if (e.key === 's') {
      currentRadius = Math.max(0, currentRadius - 2);
    } else {
      return;
    }

    applyRadius(obj, currentRadius);
    canvas.requestRenderAll();
  });
&lt;/script&gt;

&lt;/body&gt;
&lt;/html&gt;</code></pre>
